Summary.ArtifactTemplate:
- resourceId: {{ result.resourceId }}
  state: {{ result.state }}
  cursor: {{ result.cursor }}{% if result.exitCode != blank %}
  exitCode: {{ result.exitCode }}{% endif %}{% if result.signal %}
  signal: {{ result.signal }}{% endif %}{% if result.historyTruncated %}
  outputHistoryTruncated: true{% endif %}{% for update in result.updates %}{% if update.kind == 'output' %}

[{{ update.stream }} cursor={{ update.cursor }}]
{{ update.text }}{% elsif update.kind == 'state' %}

[state cursor={{ update.cursor }}] {{ update.state }}{% if update.reason %}: {{ update.reason }}{% endif %}{% endif %}{% endfor %}
